\begin{tikzpicture}
\begin{axis}[
    width=0.66\textwidth,
    height=0.58\textwidth,
    xmin=-3.2, xmax=3.2,
    ymin=-1.6, ymax=4.2,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-3,-2,-1,1,2,3},
    xticklabel=\empty,
    ytick={-1,1,2,3},
    yticklabels={\(-p\),\(p\),\(2p\),\(3p\)},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
% p=1, parabola x^2=4y -> y=x^2/4
\addplot[very thick, domain=-3:3, samples=160] {x^2/4};

% directrix
\addplot[thick, dashed, domain=-3:3, samples=2] {-1};

% focus
\addplot[only marks, mark=*] coordinates {(0,1)};
\node[anchor=north west] at (axis cs:0,1) {\(F\)};

% sample point x=2, y=1
\addplot[only marks, mark=*] coordinates {(2,1)};
\node[anchor=west] at (axis cs:2,1) {\(P\)};

% distance to focus and directrix
\draw[thick] (axis cs:2,1) -- (axis cs:0,1);
\draw[thick] (axis cs:2,1) -- (axis cs:2,-1);
\node[anchor=south] at (axis cs:1,1) {\(PF\)};
\node[anchor=west] at (axis cs:2,-0.1) {distance to directrix};

\node[anchor=west] at (axis cs:1.2,-1.15) {directrix \(y=-p\)};
\node[anchor=west] at (axis cs:1.2,3.0) {\(x^2=4py\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.80\textwidth,
    xmin=-2.6, xmax=2.6,
    ymin=-1.8, ymax=1.8,
    axis lines=middle,
    xtick={-2,0,2},
    ytick={-1,0,1},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={ellipse}
]
\addplot[very thick, domain=0:360, samples=240]
    ({2*cos(x)},{1.2*sin(x)});
\addplot[only marks, mark=*] coordinates {(-1.6,0) (1.6,0)};
\node[anchor=south] at (axis cs:-1.6,0) {\(F\)};
\node[anchor=south] at (axis cs:1.6,0) {\(F\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.80\textwidth,
    xmin=-2.7, xmax=2.7,
    ymin=-2.0, ymax=2.0,
    axis lines=middle,
    xtick={-1,0,1},
    ytick={-1,0,1},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={hyperbola}
]
\addplot[very thick, domain=1:2.5, samples=150] {0.7*sqrt(x^2-1)};
\addplot[very thick, domain=1:2.5, samples=150] {-0.7*sqrt(x^2-1)};
\addplot[very thick, domain=-2.5:-1, samples=150] {0.7*sqrt(x^2-1)};
\addplot[very thick, domain=-2.5:-1, samples=150] {-0.7*sqrt(x^2-1)};
\addplot[thick, dashed, domain=-2.6:2.6, samples=2] {0.7*x};
\addplot[thick, dashed, domain=-2.6:2.6, samples=2] {-0.7*x};
\addplot[only marks, mark=*] coordinates {(-1.22,0) (1.22,0)};
\node[anchor=south] at (axis cs:-1.22,0) {\(F\)};
\node[anchor=south] at (axis cs:1.22,0) {\(F\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}[font=\scriptsize]
\begin{axis}[
    width=0.70\textwidth,
    height=0.54\textwidth,
    xmin=-4.0, xmax=2.5,
    ymin=-4.0, ymax=4.0,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-4,-2,0,2},
    ytick={-4,-2,0,2,4},
    axis equal image,
    tick label style={font=\scriptsize},
    label style={font=\scriptsize},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-4:4, samples=200]
    ({2-x^2/8},{x});

\addplot[only marks, mark=*] coordinates {(0,0) (2,0)};
\node[anchor=south east] at (axis cs:0,0) {focus};
\node[anchor=south east] at (axis cs:2,0) {vertex};
\node[anchor=west] at (axis cs:-3.7,3.2) {\(r=\tfrac{4}{1+\cos\theta}\)};
\node[anchor=west] at (axis cs:-3.7,-2.4) {\(y^2=-8(x-2)\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-2.8, xmax=2.8,
    ymin=-2.8, ymax=2.8,
    axis lines=middle,
    xtick=\empty,
    ytick=\empty,
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(e=0.5\)}
]
\addplot[very thick, domain=0:6.283185, samples=300]
    ({(2/(1+0.5*cos(deg(x))))*cos(deg(x))},
     {(2/(1+0.5*cos(deg(x))))*sin(deg(x))});
\end{axis}

\node[font=\small\bfseries, anchor=north, yshift=-6pt] at (current bounding box.south) {ellipse};
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-4.0, xmax=2.4,
    ymin=-3.2, ymax=3.2,
    axis lines=middle,
    xtick=\empty,
    ytick=\empty,
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(e=1\)}
]
\addplot[very thick, domain=-2.45:2.45, samples=260]
    ({(2/(1+cos(deg(x))))*cos(deg(x))},
     {(2/(1+cos(deg(x))))*sin(deg(x))});
\end{axis}

\node[font=\small\bfseries, anchor=north, yshift=-6pt] at (current bounding box.south) {parabola};
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-4.0, xmax=2.4,
    ymin=-3.4, ymax=3.4,
    axis lines=middle,
    xtick=\empty,
    ytick=\empty,
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(e=1.4\)}
]
\addplot[very thick, domain=-2.1:2.1, samples=260]
    ({(2/(1+1.4*cos(deg(x))))*cos(deg(x))},
     {(2/(1+1.4*cos(deg(x))))*sin(deg(x))});
\end{axis}

\node[font=\small\bfseries, anchor=north, yshift=-6pt] at (current bounding box.south) {hyperbola branch};
\end{tikzpicture}
